-- ================================================================
-- CIVICBRAIN STEP 13 - LOAD FINAL SCHEDULE
-- Source: final_step13_schedule_candidate.csv
-- Validated scheduled jobs: 238
-- ================================================================

BEGIN;

TRUNCATE TABLE
    step13_schedule_job,
    step13_schedules
RESTART IDENTITY;



COMMIT;

-- ================================================================
-- VERIFICATION
-- ================================================================

SELECT COUNT(*) AS schedule_header_count FROM step13_schedules;

SELECT COUNT(*) AS scheduled_job_count FROM step13_schedule_job;

SELECT COUNT(DISTINCT job_id) AS unique_scheduled_jobs FROM step13_schedule_job;

SELECT s.team_id, COUNT(*) AS schedule_count FROM step13_schedules s GROUP BY s.team_id ORDER BY s.team_id;

SELECT s.schedule_status, COUNT(*) AS count FROM step13_schedules s GROUP BY s.schedule_status ORDER BY s.schedule_status;

SELECT MIN(planned_start) AS earliest_start, MAX(planned_end) AS latest_end FROM step13_schedule_job;